"use client";

import { useSyncExternalStore } from "react";

/**
 * Scope for the "Atribuir Tarefa" user picker.
 *
 * The assign/delegate modal (`CommonUserTaskModalForm`) is generated by Studio
 * and calls `useBusinessUsers()` with no arguments, so it has no direct way to
 * receive the task it is assigning. This tiny external store carries the
 * candidate groups of the task being assigned from the flow that opens the
 * modal (list row action or task-detail "Delegar") into that hook, so the user
 * dropdown can be scoped to users who actually belong to the task's candidate
 * groups — instead of listing every user of the application.
 *
 * `undefined` means "no scope" → the picker lists all application users
 * (the previous behaviour). The process-tasks filter must keep showing all
 * users, so it reads users through `useAllBusinessUsers()`, which ignores this
 * store.
 */
let candidateGroups: string | undefined;
const listeners = new Set<() => void>();

function emit() {
  for (const l of listeners) l();
}

/** Scope the assign user picker to a task's candidate groups (comma-separated). */
export function setAssignCandidateGroups(groups?: string): void {
  const next = groups?.trim() ? groups : undefined;
  if (next === candidateGroups) return;
  candidateGroups = next;
  emit();
}

/** Clear the scope → the picker lists all application users again. */
export function clearAssignCandidateGroups(): void {
  setAssignCandidateGroups(undefined);
}

function subscribe(cb: () => void): () => void {
  listeners.add(cb);
  return () => {
    listeners.delete(cb);
  };
}

function getSnapshot(): string | undefined {
  return candidateGroups;
}

/** Reactive read of the current assign scope (server snapshot is always undefined). */
export function useAssignCandidateGroups(): string | undefined {
  return useSyncExternalStore(subscribe, getSnapshot, () => undefined);
}
